llm-request-response-contract.code:
// Request: model + messages + max_tokens are the contract.
const request = {
  model: "claude-haiku-4-5",
  max_tokens: 512,                 // REQUIRED by Anthropic; caps output length
  messages: [{ role: "user", content: "Summarize this in one sentence." }],
};

// Response envelope you must actually read (never just .content):
function handle(res) {
  const text = res.content?.[0]?.text ?? "";
  if (res.stop_reason === "max_tokens") {
    // Output was TRUNCATED — do not treat 'text' as complete.
    return { text, complete: false };
  }
  // usage is your cost + a latency proxy on every call.
  return { text, complete: true, cost: res.usage };
}

