tokens-context-window.code:
const estimateTokens = (s) => Math.ceil(s.length / 4);   // ~4 chars/token, estimate only
const WINDOW = 8000, RESERVE_OUTPUT = 1000;
function budget(messages) {
  const inputBudget = WINDOW - RESERVE_OUTPUT;      // room for input
  let msgs = [...messages];
  const cost = () => msgs.reduce((n, m) => n + estimateTokens(m.content), 0);
  // drop the oldest NON-system message until we fit
  while (cost() > inputBudget && msgs.length > 1) {
    const i = msgs.findIndex(m => m.role !== "system");
    if (i === -1) break;
    msgs.splice(i, 1);
  }
  return { messages: msgs, tokens: cost(), fits: cost() <= inputBudget };
}

