streaming-responses.code:
// Provider-agnostic shape: each event carries either a text delta or terminal metadata.
function consume(events) {
  let text = "", stop = null, outputTokens = 0;
  for (const e of events) {
    if (e.type === "delta") text += e.text;               // partial output
    if (e.type === "final") { stop = e.stop_reason; outputTokens = e.output_tokens; }
  }
  return { text, stop, outputTokens };                    // read terminal metadata, not just text
}

