const tools = [{ name: "get_weather", input_schema: {
  type: "object", required: ["city"],
  properties: { city: { type: "string" }, unit: { type: "string", enum: ["C", "F"] } } }}];

function runToolCall(call, tools, impls) {
  const tool = tools.find(t => t.name === call.name);
  if (!tool) return { error: "unknown tool" };            // model asked for a tool you don't expose
  let args; try { args = JSON.parse(call.arguments); } catch { return { error: "arguments not JSON" }; }
  for (const k of tool.input_schema.required)             // validate BEFORE executing
    if (!(k in args)) return { error: "missing arg " + k };
  return { result: impls[call.name](args) };              // now safe to run your real function
}

