const estTok = (s) => Math.ceil(s.length / 4);
function addTurn(state, role, content, budget) {
  const s = [...state];
  if (s.at(-1)?.role === role) s[s.length - 1] = { role, content: s.at(-1).content + " " + content }; // merge
  else s.push({ role, content });
  const cost = () => s.reduce((n, m) => n + estTok(m.content), 0);
  while (cost() > budget && s.length > 1) {              // trim oldest non-system
    const i = s.findIndex(m => m.role !== "system");
    if (i === -1) break;
    s.splice(i, 1);
  }
  return s;
}

