function triage(status) {
  if (status >= 200 && status < 300) return { action: "ok" };
  if (status === 429) return { action: "retry", why: "rate limited — back off + honor Retry-After" };
  if (status >= 500) return { action: "retry", why: "server/overloaded (incl. 529) — back off" };
  if (status === 400 || status === 422 || status === 413) return { action: "fix_request", why: "malformed — do not retry" };
  if (status === 401 || status === 403) return { action: "fix_auth", why: "bad key/permission — do not retry" };
  return { action: "investigate", why: "unexpected status" };
}

