// Admit at most 'max' requests within any 'windowMs' span.
function makeLimiter(max, windowMs) {
  const times = [];
  return (now) => {
    while (times.length && times[0] <= now - windowMs) times.shift(); // evict old
    if (times.length < max) { times.push(now); return "allow"; }
    return "throttle";                                                // caller waits / queues
  };
}

