// moderation result: category -> score in [0,1]
function gate(moderation, threshold) {
  const flagged = Object.entries(moderation.categories)
    .filter(([, score]) => score >= threshold)
    .map(([name]) => name);
  return { allow: flagged.length === 0, flagged };
}
// enforce on input BEFORE calling the model, and on output before returning it.

