// primitives from earlier lessons, composed:
const triage = (s) => (s === 429 || s >= 500) ? "retry" : (s >= 400 ? "fix" : "ok");
const backoff = (attempt, base, cap) => Math.min(cap, base * 2 ** attempt);
const cost = (inTok, outTok) => inTok / 1e6 * 3 + outTok / 1e6 * 15;
function parseSSE(raw) {
  let text = "", stop = null;
  for (const line of raw.split("\n")) {
    if (!line.startsWith("data: ")) continue;
    const p = line.slice(6); if (p === "[DONE]") break;
    const o = JSON.parse(p); if (o.delta) text += o.delta; if (o.stop_reason) stop = o.stop_reason;
  }
  return { text, stop };
}

